result.args:
位置参数数组：[input: {
    /** 相对当前文档脚本目录、扩展名为小写 .lua 的逻辑路径；不得越界、与已有普通脚本或内联模块重名，或进入系统命名空间。 */
    path: string;
    /** 可选的非空 Lua 源码字符串；省略时正文为 return {}。包含生成的文件头后，完整 UTF-8 大小最多 1 MiB。
    禁止包含 ---@id 和 ---@referenceName 注解；复制已有源码时先移除这两个注解。 */
    content?: string;
}]
args[0] input: 相对路径与可选初始源码；仅创建普通脚本，不接受 id 或 referenceName 参数。

result.returns:
{
    /** 脚本定义句柄，严格等于 id，不带前缀；可直接读取源码头部的 ID 注解。 */
    handle: ScriptHandle;
    /** 系统为新脚本生成的未被占用的小写 UUID v4。 */
    id: string;
    /** 相对当前文档根目录的实际源码位置；AI WPrefab 使用 scripts/ 下的路径。 */
    filePath: string;
    /** 根据输入 path 将 / 替换为 _ 生成的运行时查询名称，保留 .lua 后缀；与 id 一并写入源码文件头。 */
    referenceName: string;
}
创建后的脚本标识和文件路径，供后续编辑与绑定使用。
创建并登记 Lua 文件；普通新脚本省略 content 创建骨架，再按返回的 filePath 编辑正文。
已有路径拒绝覆盖。
类型约定：
ScriptHandle：Lua 定义身份；不能代替节点或绑定身份。
WPrefab 宿主返回实际脚本 ID，不带前缀；handle 与 id 相同，可从 Lua 头部的 ID 注解读取。未挂载 builtin 使用供给方永久 ID。
